// Artwork filtering for the gallery medium pages (gallery-<medium>.html).
//
// The filter bar is generated by build.mjs from content/artworks.json, so every
// dropdown option here corresponds to at least one artwork on the page. This
// script reads the selected options plus the optional year range, hides the
// cards that do not match, and shows a no-matches message when nothing is left.
// It also keeps each artwork image's alt text in the language the page is
// currently showing, which CSS cannot do because alt is an attribute rather
// than text content.

document.addEventListener('DOMContentLoaded', function () {
  const grid = document.querySelector('.artwork-grid');
  const cards = [...document.querySelectorAll('.artwork-card')];
  const noMatches = document.querySelector('.artwork-no-matches');
  const clearButton = document.querySelector('.filter-clear');
  const yearFrom = document.querySelector('.filter-year-from');
  const yearTo = document.querySelector('.filter-year-to');

  function syncImageAltLanguage() {
    const zh = document.body.classList.contains('chinese');
    document.querySelectorAll('.artwork-image').forEach((image) => {
      const alt = zh ? image.dataset.altZh : image.dataset.altEn;
      if (alt) image.setAttribute('alt', alt);
    });
  }
  syncImageAltLanguage();
  document.querySelectorAll('.lang-btn').forEach((button) => button.addEventListener('click', syncImageAltLanguage));

  function closeDropdown(dropdown) {
    // If focus is currently inside the panel being closed, move it
    // back to the toggle button first — otherwise closing the panel
    // (display: none) strands focus and the browser resets it to
    // <body>, disorienting keyboard/screen-reader users.
    if (dropdown.contains(document.activeElement)) {
      dropdown.querySelector('.filter-dropdown-toggle').focus();
    }
    dropdown.classList.remove('open');
    dropdown.querySelector('.filter-dropdown-toggle').setAttribute('aria-expanded', 'false');
  }

  function closeAllExcept(except) {
    document.querySelectorAll('.filter-dropdown.open').forEach((d) => {
      if (d !== except) closeDropdown(d);
    });
  }

  document.querySelectorAll('.filter-dropdown').forEach((dropdown) => {
    const toggle = dropdown.querySelector('.filter-dropdown-toggle');
    toggle.addEventListener('click', () => {
      const isOpen = dropdown.classList.contains('open');
      closeAllExcept(dropdown);
      if (isOpen) {
        closeDropdown(dropdown);
      } else {
        dropdown.classList.add('open');
        toggle.setAttribute('aria-expanded', 'true');
      }
    });
  });

  document.addEventListener('click', (e) => {
    if (!e.target.closest('.filter-dropdown')) {
      closeAllExcept(null);
    }
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      closeAllExcept(null);
    }
  });

  if (cards.length === 0) return;

  function applyFilters() {
    const selected = new Map();
    document.querySelectorAll('.filter-option.selected').forEach((option) => {
      const facet = option.dataset.facet;
      if (!selected.has(facet)) selected.set(facet, new Set());
      selected.get(facet).add(option.dataset.value);
    });

    const from = yearFrom && yearFrom.value !== '' ? Number(yearFrom.value) : null;
    const to = yearTo && yearTo.value !== '' ? Number(yearTo.value) : null;

    let visibleCount = 0;
    for (const card of cards) {
      let matches = true;
      for (const [facet, wanted] of selected) {
        // data-colors holds a space-separated list; every other facet holds a
        // single value. Splitting covers both without a special case.
        const cardValues = (card.dataset[facet] || '').split(' ').filter(Boolean);
        if (!cardValues.some((value) => wanted.has(value))) {
          matches = false;
          break;
        }
      }
      if (matches) {
        const year = Number(card.dataset.year);
        if (from !== null && year < from) matches = false;
        if (to !== null && year > to) matches = false;
      }
      card.hidden = !matches;
      if (matches) visibleCount += 1;
    }

    if (noMatches) noMatches.hidden = visibleCount > 0;
    if (grid) grid.hidden = visibleCount === 0;
    if (clearButton) clearButton.hidden = selected.size === 0 && from === null && to === null;
  }

  document.querySelectorAll('.filter-option').forEach((option) => {
    option.addEventListener('click', () => {
      const nowSelected = !option.classList.contains('selected');
      option.classList.toggle('selected', nowSelected);
      option.setAttribute('aria-checked', String(nowSelected));
      applyFilters();
    });
  });

  if (yearFrom) yearFrom.addEventListener('input', applyFilters);
  if (yearTo) yearTo.addEventListener('input', applyFilters);

  if (clearButton) {
    clearButton.addEventListener('click', () => {
      document.querySelectorAll('.filter-option.selected').forEach((option) => {
        option.classList.remove('selected');
        option.setAttribute('aria-checked', 'false');
      });
      if (yearFrom) yearFrom.value = '';
      if (yearTo) yearTo.value = '';
      applyFilters();
    });
  }

  applyFilters();
});
